    DispersionPresenter,                 # Presentation of dispersion plots
    FiberFormPresenter,                  # Fiber configuration form
    LayerStackController,                # Management of the optical layer stack
    NavigationController,                # Navigation between wizard pages
    SimulationSessionState,             # Simulation session state
    SimulationRunController,            # Simulation execution
    bind_main_window_events,             # Connects all signals and slots of the main window
    disable_analyte_inputs,              # Disables analyte fields
    disable_layer_inputs,                # Disables layer fields
